import numpy as np

def stats(t: np.ndarray) -> dict:
    return {"moyenne": t.mean(), "mediane": float(np.median(t)), "ecart_type": t.std()}

def binariser(t: np.ndarray, seuil: float = 5) -> np.ndarray:
    return np.where(t < seuil, 0, 1)

# tests/test_stats.py
def test_stats():
    assert stats(np.array([1, 2, 3]))["mediane"] == 2

def test_binariser():
    assert binariser(np.array([1, 5, 9])).tolist() == [0, 1, 1]
