import pytest

def cesar(texte: str, decalage: int) -> str:
    res = []
    for c in texte:
        if c.isalpha():
            base = ord("A") if c.isupper() else ord("a")
            res.append(chr((ord(c) - base + decalage) % 26 + base))
        else:
            res.append(c)
    return "".join(res)

def decoder(texte: str, decalage: int) -> str:
    return cesar(texte, -decalage)

@pytest.mark.parametrize("k", [1, 3, 13, 25])
def test_aller_retour(k):
    t = "Bonjour, le Monde !"
    assert decoder(cesar(t, k), k) == t
